 47	package com.pousadamarealta.web;
 48	
 49	import com.fasterxml.jackson.databind.ObjectMapper;
 50	import com.fasterxml.jackson.databind.SerializationFeature;
 51	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 52	import com.pousadamarealta.dto.ReceiptDto;
 53	import com.pousadamarealta.exception.*;
 54	import com.pousadamarealta.model.*;
 55	import com.pousadamarealta.repository.MessageRepository;
 56	import com.pousadamarealta.repository.RoomRepository;
 57	import com.pousadamarealta.service.ReportService;
 58	import com.pousadamarealta.service.ReservationService;
 59	import io.javalin.Javalin;
 60	import io.javalin.http.Context;
 61	
 62	import java.time.LocalDate;
 63	import java.time.format.DateTimeFormatter;
 64	import java.time.format.DateTimeParseException;
 65	import java.util.List;
 66	import java.util.Map;
 67	import java.util.stream.Collectors;
 68	
 69	public class ApiController {
 70	    private final RoomRepository roomRepository;
 71	    private final ReservationService reservationService;
 72	    private final MessageRepository messageRepository;
 73	    private final ReportService reportService;
 74	    private final ObjectMapper objectMapper;
 75	
 76	    public ApiController(
 77	            RoomRepository roomRepository,
 78	            ReservationService reservationService,
 79	            MessageRepository messageRepository,
 80	            ReportService reportService) {
 81	        this.roomRepository = roomRepository;
 82	        this.reservationService = reservationService;
 83	        this.messageRepository = messageRepository;
 84	        this.reportService = reportService;
 85	        this.objectMapper = new ObjectMapper();
 86	        this.objectMapper.registerModule(new JavaTimeModule());
 87	        this.objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 88	    }
 89	
 90	    public void registerRoutes(Javalin app) {
 91	        app.get("/rooms", this::getRooms);
 92	        app.post("/reservations", this::createReservation);
 93	        app.get("/reservations/{id}", this::getReservation);
 94	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
 95	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
 96	        app.post("/reservations/{id}/check-in", this::checkIn);
 97	        app.post("/reservations/{id}/check-out", this::checkOut);
 98	        app.get("/reservations/{id}/document", this::getDocument);
 99	        app.get("/messages", this::getMessages);
100	        app.get("/reports/occupancy", this::getOccupancyReport);
101	        app.get("/reports/revenue", this::getRevenueReport);
102	        app.get("/reports/tourism-tax", this::getTourismTaxReport);
103	        app.get("/reports/rate-plans", this::getRatePlansReport);
104	
105	        app.exception(InvalidRequestException.class, (e, ctx) -> {
106	            ctx.status(400).json(Map.of(
107	                    "error", "INVALID_REQUEST",
108	                    "message", e.getMessage()
109	            ));
110	        });
111	
112	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
113	            ctx.status(404).json(Map.of(
114	                    "error", "ROOM_NOT_FOUND",
115	                    "message", e.getMessage()
116	            ));
117	        });
118	
119	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
120	            ctx.status(404).json(Map.of(
121	                    "error", "RESERVATION_NOT_FOUND",
122	                    "message", e.getMessage()
123	            ));
124	        });
125	
126	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
127	            ctx.status(409).json(Map.of(
128	                    "error", "ROOM_UNAVAILABLE",
129	                    "message", e.getMessage()
130	            ));
131	        });
132	
133	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
134	            ctx.status(409).json(Map.of(
135	                    "error", "OPERATION_NOT_ALLOWED",
136	                    "message", e.getMessage()
137	            ));
138	        });
139	
140	        app.exception(CapacityExceededException.class, (e, ctx) -> {
141	            ctx.status(422).json(Map.of(
142	                    "error", "CAPACITY_EXCEEDED",
143	                    "message", e.getMessage()
144	            ));
145	        });
146	    }
147	
148	    private void getRooms(Context ctx) {
149	        List<Room> rooms = roomRepository.findAll();
150	        List<Map<String, Object>> response = rooms.stream()
151	                .<Map<String, Object>>map(room -> Map.of(
152	                        "number", room.getNumber(),
153	                        "type", room.getType().name(),
154	                        "capacity", room.getCapacity(),
155	                        "nightlyRate", room.getNightlyRate()
156	                ))
157	                .collect(Collectors.toList());
158	        ctx.json(response);
159	    }
160	
161	    private void createReservation(Context ctx) {
162	        try {
163	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
164	
165	            String roomNumber = getRequiredString(body, "roomNumber");
166	            String guestName = getRequiredString(body, "guestName");
167	            String guestEmail = getRequiredString(body, "guestEmail");
168	            String guestCpf = getRequiredString(body, "guestCpf");
169	            LocalDate checkIn = parseDate(getRequiredString(body, "checkIn"));
170	            LocalDate checkOut = parseDate(getRequiredString(body, "checkOut"));
171	            int guests = getRequiredInt(body, "guests");
172	            RatePlan ratePlan = RatePlan.valueOf(getRequiredString(body, "ratePlan"));
173	
174	            Reservation reservation = reservationService.createReservation(
175	                    roomNumber, guestName, guestEmail, guestCpf,
176	                    checkIn, checkOut, guests, ratePlan);
177	
178	            ctx.status(201).json(toReservationDto(reservation));
179	        } catch (IllegalArgumentException | DateTimeParseException e) {
180	            throw new InvalidRequestException("Invalid request format");
181	        }
182	    }
183	
184	    private void getReservation(Context ctx) {
185	        Long id = parseId(ctx.pathParam("id"));
186	        Reservation reservation = reservationService.getReservation(id);
187	        ctx.json(toReservationDto(reservation));
188	    }
189	
190	    private void confirmReservation(Context ctx) {
191	        Long id = parseId(ctx.pathParam("id"));
192	        Reservation reservation = reservationService.confirmReservation(id);
193	        ctx.json(toReservationDto(reservation));
194	    }
195	
196	    private void cancelReservation(Context ctx) {
197	        Long id = parseId(ctx.pathParam("id"));
198	        Reservation reservation = reservationService.cancelReservation(id);
199	        ctx.json(toReservationDto(reservation));
200	    }
201	
202	    private void checkIn(Context ctx) {
203	        Long id = parseId(ctx.pathParam("id"));
204	        Reservation reservation = reservationService.checkIn(id);
205	        ctx.json(toReservationDto(reservation));
206	    }
207	
208	    private void checkOut(Context ctx) {
209	        Long id = parseId(ctx.pathParam("id"));
210	        ReceiptDto receipt = reservationService.checkOut(id);
211	        ctx.json(toReceiptMap(receipt));
212	    }
213	
214	    private void getDocument(Context ctx) {
215	        Long id = parseId(ctx.pathParam("id"));
216	        ReceiptDto receipt = reservationService.getDocument(id);
217	        ctx.json(toReceiptMap(receipt));
218	    }
219	
220	    private void getMessages(Context ctx) {
221	        List<Message> messages = messageRepository.findAll();
222	        List<Map<String, Object>> response = messages.stream()
223	                .<Map<String, Object>>map(msg -> Map.of(
224	                        "id", msg.getId(),
225	                        "channel", msg.getChannel(),
226	                        "to", msg.getTo(),
227	                        "subject", msg.getSubject(),
228	                        "body", msg.getBody()
229	                ))
230	                .collect(Collectors.toList());
231	        ctx.json(response);
232	    }
233	
234	    private void getOccupancyReport(Context ctx) {
235	        String dateStr = ctx.queryParam("date");
236	        if (dateStr == null) {
237	            throw new InvalidRequestException("Missing date parameter");
238	        }
239	        LocalDate date = parseDate(dateStr);
240	        String csv = reportService.generateOccupancyReport(date);
241	        ctx.contentType("text/csv; charset=utf-8").result(csv);
242	    }
243	
244	    private void getRevenueReport(Context ctx) {
245	        String monthStr = ctx.queryParam("month");
246	        if (monthStr == null) {
247	            throw new InvalidRequestException("Missing month parameter");
248	        }
249	        var parsed = parseMonth(monthStr);
250	        String csv = reportService.generateRevenueReport(parsed[0], parsed[1]);
251	        ctx.contentType("text/csv; charset=utf-8").result(csv);
252	    }
253	
254	    private void getTourismTaxReport(Context ctx) {
255	        String monthStr = ctx.queryParam("month");
256	        if (monthStr == null) {
257	            throw new InvalidRequestException("Missing month parameter");
258	        }
259	        var parsed = parseMonth(monthStr);
260	        String csv = reportService.generateTourismTaxReport(parsed[0], parsed[1]);
261	        ctx.contentType("text/csv; charset=utf-8").result(csv);
262	    }
263	
264	    private void getRatePlansReport(Context ctx) {
265	        String monthStr = ctx.queryParam("month");
266	        if (monthStr == null) {
267	            throw new InvalidRequestException("Missing month parameter");
268	        }
269	        var parsed = parseMonth(monthStr);
270	        String csv = reportService.generateRatePlansReport(parsed[0], parsed[1]);
271	        ctx.contentType("text/csv; charset=utf-8").result(csv);
272	    }
273	
274	    private Map<String, Object> toReservationDto(Reservation r) {
275	        return Map.ofEntries(
276	                Map.entry("id", r.getId()),
277	                Map.entry("roomNumber", r.getRoomNumber()),
278	                Map.entry("guestName", r.getGuestName()),
279	                Map.entry("guestEmail", r.getGuestEmail()),
280	                Map.entry("guestCpf", r.getGuestCpf()),
281	                Map.entry("checkIn", r.getCheckIn().toString()),
282	                Map.entry("checkOut", r.getCheckOut().toString()),
283	                Map.entry("guests", r.getGuests()),
284	                Map.entry("ratePlan", r.getRatePlan().name()),
285	                Map.entry("nights", r.getNights()),
286	                Map.entry("subtotal", r.getSubtotal()),
287	                Map.entry("discount", r.getDiscount()),
288	                Map.entry("total", r.getTotal()),
289	                Map.entry("status", r.getStatus().name()),
290	                Map.entry("amountPaid", r.getAmountPaid()),
291	                Map.entry("refund", r.getRefund())
292	        );
293	    }
294	
295	    private Map<String, Object> toReceiptMap(ReceiptDto receipt) {
296	        return Map.ofEntries(
297	                Map.entry("title", receipt.title()),
298	                Map.entry("reservationId", receipt.reservationId()),
299	                Map.entry("guestName", receipt.guestName()),
300	                Map.entry("guestCpf", receipt.guestCpf()),
301	                Map.entry("roomNumber", receipt.roomNumber()),
302	                Map.entry("roomType", receipt.roomType()),
303	                Map.entry("checkIn", receipt.checkIn().toString()),
304	                Map.entry("checkOut", receipt.checkOut().toString()),
305	                Map.entry("nights", receipt.nights()),
306	                Map.entry("subtotal", receipt.subtotal()),
307	                Map.entry("discount", receipt.discount()),
308	                Map.entry("total", receipt.total())
309	        );
310	    }
311	
312	    private String getRequiredString(Map<String, Object> map, String key) {
313	        Object value = map.get(key);
314	        if (value == null) {
315	            throw new InvalidRequestException("Missing field: " + key);
316	        }
317	        return value.toString();
318	    }
319	
320	    private int getRequiredInt(Map<String, Object> map, String key) {
321	        Object value = map.get(key);
322	        if (value == null) {
323	            throw new InvalidRequestException("Missing field: " + key);
324	        }
325	        if (value instanceof Number) {
326	            return ((Number) value).intValue();
327	        }
328	        throw new InvalidRequestException("Invalid integer: " + key);
329	    }
330	
331	    private LocalDate parseDate(String dateStr) {
332	        try {
333	            return LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
334	        } catch (DateTimeParseException e) {
335	            throw new InvalidRequestException("Invalid date format: " + dateStr);
336	        }
337	    }
338	
339	    private int[] parseMonth(String monthStr) {
340	        try {
341	            String[] parts = monthStr.split("-");
342	            if (parts.length != 2) {
343	                throw new InvalidRequestException("Invalid month format: " + monthStr);
344	            }
345	            int year = Integer.parseInt(parts[0]);
346	            int month = Integer.parseInt(parts[1]);
347	            if (month < 1 || month > 12) {
348	                throw new InvalidRequestException("Invalid month: " + month);
349	            }
350	            return new int[]{year, month};
351	        } catch (NumberFormatException e) {
352	            throw new InvalidRequestException("Invalid month format: " + monthStr);
353	        }
354	    }
355	
356	    private Long parseId(String idStr) {
357	        try {
358	            return Long.parseLong(idStr);
359	        } catch (NumberFormatException e) {
360	            throw new InvalidRequestException("Invalid ID format");
361	        }
362	    }
363	}

