  9	import java.math.BigDecimal;
 10	import java.time.LocalDate;
 11	import java.time.temporal.ChronoUnit;
 12	
 13	public class ReservationService {
 14	    private final ReservationRepository reservationRepository;
 15	    private final RoomRepository roomRepository;
 16	    private final PricingService pricingService;
 17	    private final NotificationService notificationService;
 18	
 19	    public ReservationService(
 20	            ReservationRepository reservationRepository,
 21	            RoomRepository roomRepository,
 22	            PricingService pricingService,
 23	            NotificationService notificationService) {
 24	        this.reservationRepository = reservationRepository;
 25	        this.roomRepository = roomRepository;
 26	        this.pricingService = pricingService;
 27	        this.notificationService = notificationService;
 28	    }
 29	
 30	    public Reservation createReservation(
 31	            String roomNumber,
 32	            String guestName,
 33	            String guestEmail,
 34	            String guestCpf,
 35	            LocalDate checkIn,
 36	            LocalDate checkOut,
 37	            int guests,
 38	            RatePlan ratePlan) {
 39	
 40	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
 41	            throw new InvalidRequestException("Check-out must be after check-in");
 42	        }
 43	
 44	        if (guests < 1) {
 45	            throw new InvalidRequestException("At least one guest is required");
 46	        }
 47	
 48	        Room room = roomRepository.findByNumber(roomNumber)
 49	                .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
 50	
 51	        if (guests > room.getCapacity()) {
 52	            throw new CapacityExceededException("Room capacity exceeded");
 53	        }
 54	
 55	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
 56	            throw new RoomUnavailableException("Room is not available for the selected dates");
 57	        }
 58	
 59	        Reservation reservation = new Reservation();
 60	        reservation.setRoomNumber(roomNumber);
 61	        reservation.setGuestName(guestName);
 62	        reservation.setGuestEmail(guestEmail);
 63	        reservation.setGuestCpf(guestCpf);
 64	        reservation.setCheckIn(checkIn);
 65	        reservation.setCheckOut(checkOut);
 66	        reservation.setGuests(guests);
 67	        reservation.setRatePlan(ratePlan);
 68	
 69	        calculatePricing(reservation, room);
 70	
 71	        return reservationRepository.save(reservation);
 72	    }
 73	
 74	    private void calculatePricing(Reservation reservation, Room room) {
 75	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
 76	        reservation.setNights(nights);
 77	
 78	        BigDecimal subtotal = BigDecimal.ZERO;
 79	        LocalDate current = reservation.getCheckIn();
 80	        for (int i = 0; i < nights; i++) {
 81	            BigDecimal nightPrice = pricingService.calculateNightPrice(room.getNightlyRate(), current);
 82	            subtotal = subtotal.add(nightPrice);
 83	            current = current.plusDays(1);
 84	        }
 85	        subtotal = pricingService.round(subtotal);
 86	        reservation.setSubtotal(subtotal);
 87	
 88	        BigDecimal discount = BigDecimal.ZERO;
 89	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
 90	            discount = pricingService.round(subtotal.multiply(new BigDecimal("0.15")));
 91	        }
 92	        reservation.setDiscount(discount);
 93	
 94	        BigDecimal total = pricingService.round(subtotal.subtract(discount));
 95	        reservation.setTotal(total);
 96	    }
