 98	    public Reservation confirmReservation(Long id) {
 99	        Reservation reservation = reservationRepository.findById(id)
100	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
101	
102	        if (reservation.getStatus() != ReservationStatus.PENDING) {
103	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
104	        }
105	
106	        reservation.setStatus(ReservationStatus.CONFIRMED);
107	        reservation.setAmountPaid(reservation.getTotal());
108	        reservationRepository.update(reservation);
109	
110	        ReceiptDto receipt = buildReceipt(reservation);
111	        notificationService.sendConfirmationEmail(
112	                reservation.getGuestName(),
113	                reservation.getGuestEmail(),
114	                receipt);
115	
116	        return reservation;
117	    }
118	
119	    public Reservation cancelReservation(Long id) {
120	        Reservation reservation = reservationRepository.findById(id)
121	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
122	
123	        if (reservation.getStatus() != ReservationStatus.PENDING &&
124	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
125	            throw new OperationNotAllowedException("Only pending or confirmed reservations can be cancelled");
126	        }
127	
128	        reservation.setStatus(ReservationStatus.CANCELLED);
129	
130	        if (reservation.getRatePlan() == RatePlan.STANDARD &&
131	            reservation.getAmountPaid().compareTo(BigDecimal.ZERO) > 0) {
132	            reservation.setRefund(reservation.getAmountPaid());
133	        } else {
134	            reservation.setRefund(BigDecimal.ZERO);
135	        }
136	
137	        reservationRepository.update(reservation);
138	        return reservation;
139	    }
140	
141	    public Reservation checkIn(Long id) {
142	        Reservation reservation = reservationRepository.findById(id)
143	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
144	
145	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
146	            throw new OperationNotAllowedException("Only confirmed reservations can be checked in");
147	        }
148	
149	        reservation.setStatus(ReservationStatus.CHECKED_IN);
150	        reservationRepository.update(reservation);
151	        return reservation;
152	    }
153	
154	    public ReceiptDto checkOut(Long id) {
155	        Reservation reservation = reservationRepository.findById(id)
156	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
157	
158	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
159	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
160	        }
161	
162	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
163	        reservationRepository.update(reservation);
164	
165	        return buildReceipt(reservation);
166	    }
167	
168	    public ReceiptDto getDocument(Long id) {
169	        Reservation reservation = reservationRepository.findById(id)
170	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
171	
172	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
173	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
174	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
175	            throw new OperationNotAllowedException("Document only available for paid reservations");
176	        }
177	
178	        return buildReceipt(reservation);
179	    }
180	
181	    public Reservation getReservation(Long id) {
182	        return reservationRepository.findById(id)
183	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
184	    }
185	
186	    private ReceiptDto buildReceipt(Reservation reservation) {
187	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
188	
189	        return new ReceiptDto(
190	                "Comprovante de reserva",
191	                reservation.getId(),
192	                reservation.getGuestName(),
193	                reservation.getGuestCpf(),
194	                reservation.getRoomNumber(),
195	                room.getType().name(),
196	                reservation.getCheckIn(),
197	                reservation.getCheckOut(),
198	                reservation.getNights(),
199	                reservation.getSubtotal(),
200	                reservation.getDiscount(),
201	                reservation.getTotal()
202	        );
203	    }
204	}
