207	import java.math.BigDecimal;
208	import java.math.RoundingMode;
209	import java.time.LocalDate;
210	
211	public class PricingService {
212	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
213	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
214	
215	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
216	        if (isHighSeason(date)) {
217	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
218	        }
219	        return baseRate;
220	    }
221	
222	    public boolean isHighSeason(LocalDate date) {
223	        int month = date.getMonthValue();
224	        int day = date.getDayOfMonth();
225	
226	        if (month == 12 && day >= 15) {
227	            return true;
228	        }
229	        if (month == 1 || month == 2) {
230	            return true;
231	        }
232	        if (month == 7) {
233	            return true;
234	        }
235	        return false;
236	    }
237	
238	    public BigDecimal round(BigDecimal value) {
239	        return value.setScale(2, RoundingMode.HALF_EVEN);
240	    }
241	}
