244	import com.pousadamarealta.dto.ReceiptDto;
245	import com.pousadamarealta.model.Message;
246	import com.pousadamarealta.repository.MessageRepository;
247	
248	import java.math.BigDecimal;
249	import java.text.NumberFormat;
250	import java.time.LocalDate;
251	import java.time.format.DateTimeFormatter;
252	import java.util.Locale;
253	
254	public class NotificationService {
255	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
256	    private static final NumberFormat CURRENCY_FORMATTER = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
257	
258	    private final MessageRepository messageRepository;
259	
260	    public NotificationService(MessageRepository messageRepository) {
261	        this.messageRepository = messageRepository;
262	    }
263	
264	    public void sendConfirmationEmail(String guestName, String guestEmail, ReceiptDto receipt) {
265	        String subject = "Reserva confirmada - Pousada Maré Alta";
266	        String body = buildConfirmationEmail(guestName, receipt);
267	        Message message = new Message("EMAIL", guestEmail, subject, body);
268	        messageRepository.save(message);
269	    }
270	
271	    private String buildConfirmationEmail(String guestName, ReceiptDto receipt) {
272	        StringBuilder sb = new StringBuilder();
273	        sb.append("Olá, ").append(guestName).append("!\n\n");
274	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
275	        sb.append(formatReceipt(receipt));
276	        sb.append("\n");
277	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
278	        sb.append("Até breve!");
279	        return sb.toString();
280	    }
281	
282	    public String formatReceipt(ReceiptDto receipt) {
283	        StringBuilder sb = new StringBuilder();
284	        sb.append(receipt.title()).append(" nº ").append(receipt.reservationId()).append("\n");
285	        sb.append("Hóspede: ").append(receipt.guestName()).append(" (CPF ").append(formatCpf(receipt.guestCpf())).append(")\n");
286	        sb.append("Quarto: ").append(receipt.roomNumber()).append(" (").append(receipt.roomType()).append(")\n");
287	        sb.append("Entrada: ").append(formatDate(receipt.checkIn()));
288	        sb.append(" | Saída: ").append(formatDate(receipt.checkOut()));
289	        sb.append(" | ").append(receipt.nights()).append(receipt.nights() == 1 ? " diária" : " diárias").append("\n");
290	        sb.append("Diárias: ").append(formatCurrency(receipt.subtotal())).append("\n");
291	
292	        if (receipt.discount() != null && receipt.discount().compareTo(BigDecimal.ZERO) > 0) {
293	            sb.append("Desconto: ").append(formatCurrency(receipt.discount())).append("\n");
294	        }
295	
296	        sb.append("Total: ").append(formatCurrency(receipt.total()));
297	        return sb.toString();
298	    }
299	
300	    private String formatCpf(String cpf) {
301	        if (cpf.length() == 11) {
302	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
303	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
304	        }
305	        return cpf;
306	    }
307	
308	    private String formatDate(LocalDate date) {
309	        return date.format(DATE_FORMATTER);
310	    }
311	
312	    private String formatCurrency(BigDecimal amount) {
313	        return CURRENCY_FORMATTER.format(amount);
314	    }
315	}

