168	    public ReceiptDto getDocument(Long id) {
169	        Reservation reservation = reservationRepository.findById(id)
170	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
171	
172	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
173	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
174	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
175	            throw new OperationNotAllowedException("Document only available for paid reservations");
176	        }
177	
178	        return buildReceipt(reservation);
179	    }
180	
181	    public Reservation getReservation(Long id) {
182	        return reservationRepository.findById(id)
183	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
184	    }
185	
186	    private ReceiptDto buildReceipt(Reservation reservation) {
187	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
188	
189	        return new ReceiptDto(
190	                "Comprovante de reserva",
191	                reservation.getId(),
192	                reservation.getGuestName(),
193	                reservation.getGuestCpf(),
194	                reservation.getRoomNumber(),
195	                room.getType().name(),
196	                reservation.getCheckIn(),
197	                reservation.getCheckOut(),
198	                reservation.getNights(),
199	                reservation.getSubtotal(),
200	                reservation.getDiscount(),
201	                reservation.getTotal()
