  6	
  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	import java.time.format.DateTimeFormatter;
 10	import java.util.*;
 11	import java.util.stream.Collectors;
 12	
 13	public class ReportService {
 14	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 15	    private static final BigDecimal TOURISM_TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
 16	
 17	    private final ReservationRepository reservationRepository;
 18	    private final RoomRepository roomRepository;
 19	
 20	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
 21	        this.reservationRepository = reservationRepository;
 22	        this.roomRepository = roomRepository;
 23	    }
 24	
 25	    public String generateOccupancyReport(LocalDate date) {
 26	        List<ReservationStatus> paidStatuses = List.of(
 27	                ReservationStatus.CONFIRMED,
 28	                ReservationStatus.CHECKED_IN,
 29	                ReservationStatus.CHECKED_OUT
 30	        );
 31	
 32	        List<Reservation> reservations = reservationRepository.findByDateAndStatus(date, paidStatuses);
 33	        List<Room> allRooms = roomRepository.findAll();
 34	
 35	        StringBuilder csv = new StringBuilder();
 36	        csv.append("Pousada Maré Alta,occupancy,").append(date.format(DATE_FORMATTER)).append("\n");
 37	        csv.append("room,type,reservation,check_in,check_out\n");
 38	
 39	        for (Reservation r : reservations) {
 40	            Room room = allRooms.stream()
 41	                    .filter(rm -> rm.getNumber().equals(r.getRoomNumber()))
 42	                    .findFirst()
 43	                    .orElseThrow();
 44	
 45	            csv.append(r.getRoomNumber()).append(",");
 46	            csv.append(room.getType().name()).append(",");
 47	            csv.append(r.getId()).append(",");
 48	            csv.append(r.getCheckIn().format(DATE_FORMATTER)).append(",");
 49	            csv.append(r.getCheckOut().format(DATE_FORMATTER)).append("\n");
 50	        }
 51	
 52	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
 53	        return csv.toString();
 54	    }
 55	
 56	    public String generateRevenueReport(int year, int month) {
 57	        List<Reservation> allReservations = reservationRepository.findByMonth(year, month);
 58	
 59	        List<Reservation> revenueReservations = allReservations.stream()
 60	                .filter(r -> r.getStatus() != ReservationStatus.PENDING)
 61	                .collect(Collectors.toList());
 62	
 63	        StringBuilder csv = new StringBuilder();
 64	        csv.append("Pousada Maré Alta,revenue,").append(String.format("%04d-%02d", year, month)).append("\n");
 65	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 66	
 67	        BigDecimal totalRevenue = BigDecimal.ZERO;
 68	
 69	        for (Reservation r : revenueReservations) {
 70	            BigDecimal revenue = calculateRevenue(r);
 71	            totalRevenue = totalRevenue.add(revenue);
 72	
 73	            csv.append(r.getId()).append(",");
 74	            csv.append(r.getRoomNumber()).append(",");
 75	            csv.append(r.getCheckIn().format(DATE_FORMATTER)).append(",");
 76	            csv.append(r.getCheckOut().format(DATE_FORMATTER)).append(",");
 77	            csv.append(r.getStatus().name()).append(",");
 78	            csv.append(formatAmount(revenue)).append("\n");
 79	        }
 80	
 81	        csv.append("total,").append(formatAmount(totalRevenue));
 82	        return csv.toString();
 83	    }
 84	
 85	    public String generateTourismTaxReport(int year, int month) {
 86	        List<Reservation> allReservations = reservationRepository.findByMonth(year, month);
 87	
 88	        List<Reservation> paidReservations = allReservations.stream()
 89	                .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
 90	                             r.getStatus() == ReservationStatus.CHECKED_IN ||
 91	                             r.getStatus() == ReservationStatus.CHECKED_OUT)
 92	                .collect(Collectors.toList());
 93	
 94	        StringBuilder csv = new StringBuilder();
 95	        csv.append("Pousada Maré Alta,tourism-tax,").append(String.format("%04d-%02d", year, month)).append("\n");
 96	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
 97	
 98	        BigDecimal totalTax = BigDecimal.ZERO;
 99	
100	        for (Reservation r : paidReservations) {
101	            BigDecimal tax = calculateTourismTax(r);
102	            totalTax = totalTax.add(tax);
103	
104	            csv.append(r.getId()).append(",");
105	            csv.append(r.getRoomNumber()).append(",");
106	            csv.append(r.getCheckIn().format(DATE_FORMATTER)).append(",");
107	            csv.append(r.getCheckOut().format(DATE_FORMATTER)).append(",");
108	            csv.append(r.getGuests()).append(",");
109	            csv.append(r.getNights()).append(",");
110	            csv.append(formatAmount(tax)).append("\n");
111	        }
112	
113	        csv.append("total,").append(formatAmount(totalTax));
114	        return csv.toString();
115	    }
116	
117	    public String generateRatePlansReport(int year, int month) {
118	        List<Reservation> allReservations = reservationRepository.findByMonth(year, month);
119	
120	        List<Reservation> revenueReservations = allReservations.stream()
121	                .filter(r -> r.getStatus() != ReservationStatus.PENDING)
122	                .collect(Collectors.toList());
123	
124	        Map<RatePlan, List<Reservation>> byPlan = revenueReservations.stream()
125	                .collect(Collectors.groupingBy(Reservation::getRatePlan));
126	
127	        StringBuilder csv = new StringBuilder();
128	        csv.append("Pousada Maré Alta,rate-plans,").append(String.format("%04d-%02d", year, month)).append("\n");
129	        csv.append("rate_plan,reservations,amount\n");
130	
131	        int totalCount = 0;
132	        BigDecimal totalAmount = BigDecimal.ZERO;
133	
134	        for (RatePlan plan : RatePlan.values()) {
135	            List<Reservation> planReservations = byPlan.getOrDefault(plan, Collections.emptyList());
136	            int count = planReservations.size();
137	            BigDecimal amount = planReservations.stream()
138	                    .map(this::calculateRevenue)
139	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
140	
141	            csv.append(plan.name()).append(",");
142	            csv.append(count).append(",");
143	            csv.append(formatAmount(amount)).append("\n");
144	
145	            totalCount += count;
146	            totalAmount = totalAmount.add(amount);
147	        }
148	
149	        csv.append("total,").append(totalCount).append(",").append(formatAmount(totalAmount));
150	        return csv.toString();
151	    }
152	
153	    private BigDecimal calculateRevenue(Reservation r) {
154	        BigDecimal paid = r.getAmountPaid();
155	        BigDecimal refunded = r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO;
156	        return paid.subtract(refunded);
157	    }
158	
159	    private BigDecimal calculateTourismTax(Reservation r) {
160	        return TOURISM_TAX_PER_GUEST_PER_NIGHT
161	                .multiply(BigDecimal.valueOf(r.getGuests()))
162	                .multiply(BigDecimal.valueOf(r.getNights()));
163	    }
164	
165	    private String formatAmount(BigDecimal amount) {
166	        return amount.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
167	    }
168	}
