230	                        channel VARCHAR(20) NOT NULL,
231	                        recipient VARCHAR(255) NOT NULL,
232	                        subject VARCHAR(500) NOT NULL,
233	                        body TEXT NOT NULL
234	                    )
235	                    """);
236	            } else {
237	                stmt.execute("""
238	                    CREATE TABLE IF NOT EXISTS reservations (
239	                        id BIGSERIAL PRIMARY KEY,
240	                        room_number VARCHAR(10) NOT NULL,
241	                        guest_name VARCHAR(255) NOT NULL,
242	                        guest_email VARCHAR(255) NOT NULL,
243	                        guest_cpf VARCHAR(20) NOT NULL,
