252	                        status VARCHAR(20) NOT NULL,
253	                        amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
254	                        refund DECIMAL(10, 2),
255	                        FOREIGN KEY (room_number) REFERENCES rooms(number)
256	                    )
257	                    """);
258	
259	                stmt.execute("""
