261	                        id BIGSERIAL PRIMARY KEY,
262	                        channel VARCHAR(20) NOT NULL,
263	                        recipient VARCHAR(255) NOT NULL,
264	                        subject VARCHAR(500) NOT NULL,
265	                        body TEXT NOT NULL
266	                    )
267	                    """);
268	            }
269	
270	            long roomCount = 0;
271	            try (var rs = stmt.executeQuery("SELECT COUNT(*) FROM rooms")) {
272	                if (rs.next()) {
273	                    roomCount = rs.getLong(1);
274	                }
275	            }
276	
277	            if (roomCount == 0) {
278	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('101', 'STANDARD')");
279	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('102', 'STANDARD')");
280	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('201', 'DELUXE')");
281	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('202', 'DELUXE')");
282	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('301', 'SUITE')");
283	            }
284	
285	        } catch (SQLException e) {
286	            throw new RuntimeException("Failed to initialize database", e);
287	        }
288	    }
