135	            List<Reservation> planReservations = byPlan.getOrDefault(plan, Collections.emptyList());
136	            int count = planReservations.size();
137	            BigDecimal amount = planReservations.stream()
138	                    .map(this::calculateRevenue)
139	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
140	
141	            csv.append(plan.name()).append(",");
142	            csv.append(count).append(",");
143	            csv.append(formatAmount(amount)).append("\n");
144	
145	            totalCount += count;
146	            totalAmount = totalAmount.add(amount);
147	        }
148	
149	        csv.append("total,").append(totalCount).append(",").append(formatAmount(totalAmount));
150	        return csv.toString();
151	    }
152	
153	    private BigDecimal calculateRevenue(Reservation r) {
154	        BigDecimal paid = r.getAmountPaid();
155	        BigDecimal refunded = r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO;
156	        return paid.subtract(refunded);
157	    }
158	
159	    private BigDecimal calculateTourismTax(Reservation r) {
160	        return TOURISM_TAX_PER_GUEST_PER_NIGHT
161	                .multiply(BigDecimal.valueOf(r.getGuests()))
162	                .multiply(BigDecimal.valueOf(r.getNights()));
163	    }
164	
165	    private String formatAmount(BigDecimal amount) {
166	        return amount.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
167	    }
168	}
