189	    public List<Reservation> findByMonth(int year, int month) {
190	        LocalDate start = LocalDate.of(year, month, 1);
191	        LocalDate end = start.plusMonths(1);
192	
193	        String sql = """
194	            SELECT id, room_number, guest_name, guest_email, guest_cpf,
195	                   check_in, check_out, guests, rate_plan,
196	                   nights, subtotal, discount, total,
197	                   status, amount_paid, refund
198	            FROM reservations
199	            WHERE check_in >= ? AND check_in < ?
200	            ORDER BY check_in, id
201	            """;
202	
203	        List<Reservation> reservations = new ArrayList<>();
204	        try (var conn = database.getConnection();
205	             var stmt = conn.prepareStatement(sql)) {
206	
207	            stmt.setDate(1, Date.valueOf(start));
208	            stmt.setDate(2, Date.valueOf(end));
209	
210	            try (var rs = stmt.executeQuery()) {
211	                while (rs.next()) {
212	                    reservations.add(mapRow(rs));
213	                }
214	            }
215	        } catch (SQLException e) {
216	            throw new RuntimeException("Failed to fetch reservations by month", e);
217	        }
218	        return reservations;
219	    }
