221	    private Reservation mapRow(ResultSet rs) throws SQLException {
222	        Reservation r = new Reservation();
223	        r.setId(rs.getLong("id"));
224	        r.setRoomNumber(rs.getString("room_number"));
225	        r.setGuestName(rs.getString("guest_name"));
226	        r.setGuestEmail(rs.getString("guest_email"));
227	        r.setGuestCpf(rs.getString("guest_cpf"));
228	        r.setCheckIn(rs.getDate("check_in").toLocalDate());
229	        r.setCheckOut(rs.getDate("check_out").toLocalDate());
230	        r.setGuests(rs.getInt("guests"));
231	        r.setRatePlan(RatePlan.valueOf(rs.getString("rate_plan")));
232	        r.setNights(rs.getInt("nights"));
233	        r.setSubtotal(rs.getBigDecimal("subtotal"));
234	        r.setDiscount(rs.getBigDecimal("discount"));
235	        r.setTotal(rs.getBigDecimal("total"));
236	        r.setStatus(ReservationStatus.valueOf(rs.getString("status")));
237	        r.setAmountPaid(rs.getBigDecimal("amount_paid"));
238	        var refund = rs.getBigDecimal("refund");
239	        if (refund != null) {
240	            r.setRefund(refund);
241	        }
242	        return r;
243	    }
